mapper.select:
select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join Sec_Document sd on sd.Sec_Id=sec.Sec_Id where sd.D_Id=#{dId}

select sec.Sec_Name as secName, sec.Sec_Type as secType, sec.Sec_Money as secMoney, sec.Sec_Bidding_Type as secBiddingType, c3.C_Name as dPersonName, c1.C_Name as dManageConsulName, c2.C_Name as dAgentUnitName, c4.C_Name as dEntrustedCpyName, c1.C_Abbreviation as dManageConAbbName, c2.C_Abbreviation as dAgentAbbName, c3.C_Abbreviation as dPersonAbbName, c4.C_Abbreviation as dEntrustedCpyAbbName, c7.C_Name as dCname, dp1.D_Name as dDname, u1.U_Name as dPmName, case when pre.P_Name is null then sp.P_Name else pre.P_Name end as pName, case when pre.P_Category is null then sp.p_Category else pre.P_Category end as pCategory, case when pre.P_Build_Model is null then sp.P_Build_Model else pre.P_Build_Model end as pBuildModel, case when dpre.D_Name is null then sp.D_Name else dpre.D_Name end as pCompetentDepartmentName, mn.*, case when mn.P_Id is null then sp.P_Id else mn.P_Id end as pId from Sec_Document mn left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Company c3 on c3.C_Id=mn.D_Person left join SYS_Company c1 on c1.C_Id=mn.D_Manage_Consul left join SYS_Company c2 on c2.C_Id=mn.D_Agent_Unit left join SYS_Company c4 on c4.C_Id=mn.D_Entrusted_Cpy left join Sys_Company c7 on c7.C_Id=mn.D_Cid left join Sys_Department dp1 on dp1.D_Id=mn.D_Did left join Sys_User u1 on u1.U_Id=mn.D_Pm_Id left join pre_project pre on pre.P_Id=mn.P_Id left join SYS_Department dpre on dpre.D_Id = pre.p_Competent_Department left join Sec_Bidding_Plan sbp on sbp.Bp_Id=sec.Bp_Id left join ( select sp1.Sec_Id, sp1.P_ID, pro1.P_Name, pro1.p_Category, pro1.P_Build_Model, dpre1.D_Name from Sec_Project sp1 inner join pre_project pro1 on pro1.P_Id = sp1.P_Id left join SYS_Department dpre1 on dpre1.D_Id = pro1.p_Competent_Department where not exists ( select 1 from Sec_Project sp2 inner join pre_project pro2 on pro2.P_Id = sp2.P_Id where sp2.Sec_Id = sp1.Sec_Id and pro2.P_Create_Time > pro1.P_Create_Time )) sp on sp.Sec_Id = mn.Sec_Id ${authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.D_Create_Time DESC
limit #{params.start},#{params.size}

select sec.Sec_Name as secName, sec.Sec_Type as secType, sec.Sec_Money as secMoney, sec.Sec_Bidding_Type as secBiddingType, c3.C_Name as dPersonName, c1.C_Name as dManageConsulName, c2.C_Name as dAgentUnitName, c4.C_Name as dEntrustedCpyName, c1.C_Abbreviation as dManageConAbbName, c2.C_Abbreviation as dAgentAbbName, c3.C_Abbreviation as dPersonAbbName, c4.C_Abbreviation as dEntrustedCpyAbbName, c7.C_Name as dCname, dp1.D_Name as dDname, u1.U_Name as dPmName, sd.*, case when sd.P_Id is null then sp.P_Id else sd.P_Id end as pId from Sec_Document sd left join Sec_Info sec on sec.Sec_Id=sd.Sec_Id left join SYS_Company c3 on c3.C_Id=sd.D_Person left join SYS_Company c1 on c1.C_Id=sd.D_Manage_Consul left join SYS_Company c2 on c2.C_Id=sd.D_Agent_Unit left join SYS_Company c4 on c4.C_Id=sd.D_Entrusted_Cpy left join Sys_Company c7 on c7.C_Id=sd.D_Cid left join Sys_Department dp1 on dp1.D_Id=sd.D_Did left join Sys_User u1 on u1.U_Id=sd.D_Pm_Id left join ( select sp1.Sec_Id, sp1.P_ID, pro1.P_Name, pro1.p_Category, pro1.P_Build_Model, dpre1.D_Name from Sec_Project sp1 inner join pre_project pro1 on pro1.P_Id = sp1.P_Id left join SYS_Department dpre1 on dpre1.D_Id = pro1.p_Competent_Department where not exists ( select 1 from Sec_Project sp2 inner join pre_project pro2 on pro2.P_Id = sp2.P_Id where sp2.Sec_Id = sp1.Sec_Id and pro2.P_Create_Time > pro1.P_Create_Time )) sp on sp.Sec_Id = sd.Sec_Id where 1=1
order by sd.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by sd.D_Create_Time DESC
limit #{params.start},#{params.size}

select sec.Sec_Name as secName, sec.Sec_Type as secType, sec.Sec_Money as secMoney, sec.Sec_Bidding_Type as secBiddingType, c3.C_Name as dPersonName, c1.C_Name as dManageConsulName, c2.C_Name as dAgentUnitName, c4.C_Name as dEntrustedCpyName, c1.C_Abbreviation as dManageConAbbName, c2.C_Abbreviation as dAgentAbbName, c3.C_Abbreviation as dPersonAbbName, c4.C_Abbreviation as dEntrustedCpyAbbName, c7.C_Name as dCname, dp1.D_Name as dDname, u1.U_Name as dPmName, sd.*, case WHEN ssr.Sr_Bid_Time is not null then ssr.Sr_Bid_Time WHEN sd.D_New_Bid_Time is not null Then sd.D_New_Bid_Time ELSE sd.D_Bid_Time END as dBidTime , ssr.Sr_Location as dNewLocation, case when sd.P_Id is null then sp.P_Id else sd.P_Id end as pId from Sec_Document sd left join Sec_Info sec on sec.Sec_Id=sd.Sec_Id left join SYS_Company c3 on c3.C_Id=sd.D_Person left join SYS_Company c1 on c1.C_Id=sd.D_Manage_Consul left join SYS_Company c2 on c2.C_Id=sd.D_Agent_Unit left join SYS_Company c4 on c4.C_Id=sd.D_Entrusted_Cpy left join Sys_Company c7 on c7.C_Id=sd.D_Cid left join Sys_Department dp1 on dp1.D_Id=sd.D_Did left join Sys_User u1 on u1.U_Id=sd.D_Pm_Id left join Sec_Selection_Record ssr on ssr.Sec_Id=sd.Sec_Id left join ( select sp1.Sec_Id, sp1.P_ID, pro1.P_Name, pro1.p_Category, pro1.P_Build_Model, dpre1.D_Name from Sec_Project sp1 inner join pre_project pro1 on pro1.P_Id = sp1.P_Id left join SYS_Department dpre1 on dpre1.D_Id = pro1.p_Competent_Department where not exists ( select 1 from Sec_Project sp2 inner join pre_project pro2 on pro2.P_Id = sp2.P_Id where sp2.Sec_Id = sp1.Sec_Id and pro2.P_Create_Time > pro1.P_Create_Time )) sp on sp.Sec_Id = sd.Sec_Id where 1=1 and (ssr.State is null or ssr.State!=3)
order by sd.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by sd.D_Create_Time DESC

select sp.P_Id as pId, sec.Sec_Name as secName, sec.Sec_Type as secType, sec.Sec_Bidding_Type as secBiddingType, c3.C_Name as dPersonName, c1.C_Name as dManageConsulName, c2.C_Name as dAgentUnitName, c4.C_Name as dEntrustedCpyName, c1.C_Abbreviation as dManageConAbbName, c2.C_Abbreviation as dAgentAbbName, c3.C_Abbreviation as dPersonAbbName, c4.C_Abbreviation as dEntrustedCpyAbbName, c7.C_Name as dCname, dp1.D_Name as dDname, u1.U_Name as dPmName, sd.*, case when sd.P_Id is null then sp.P_Id else sd.P_Id end as pId from Sec_Document sd left join Sec_Info sec on sec.Sec_Id=sd.Sec_Id left join Sec_Project sp on sec.Sec_Id=sp.Sec_Id left join SYS_Company c3 on c3.C_Id=sd.D_Person left join SYS_Company c1 on c1.C_Id=sd.D_Manage_Consul left join SYS_Company c2 on c2.C_Id=sd.D_Agent_Unit left join SYS_Company c4 on c4.C_Id=sd.D_Entrusted_Cpy left join Sys_Company c7 on c7.C_Id=sd.D_Cid left join Sys_Department dp1 on dp1.D_Id=sd.D_Did left join Sys_User u1 on u1.U_Id=sd.D_Pm_Id left join ( select sp1.Sec_Id, sp1.P_ID, pro1.P_Name, pro1.p_Category, pro1.P_Build_Model, dpre1.D_Name from Sec_Project sp1 inner join pre_project pro1 on pro1.P_Id = sp1.P_Id left join SYS_Department dpre1 on dpre1.D_Id = pro1.p_Competent_Department where not exists ( select 1 from Sec_Project sp2 inner join pre_project pro2 on pro2.P_Id = sp2.P_Id where sp2.Sec_Id = sp1.Sec_Id and pro2.P_Create_Time > pro1.P_Create_Time )) sp on sp.Sec_Id = sd.Sec_Id where 1=1
and sp.P_Id in
#{pId}

mapper.sql:
select distinct mn.P_Id, mn.P_Code, mn.P_Name, mn.P_Create_Time, sd.D_Name as pCompetentDepartmentName, (select count(1) from Sec_Info where 1=1
and Sec_Flow_State = #{params.secFlowState}
and Sec_Id in (select Sec_Id from Sec_Project where P_Id=mn.P_Id)) as secTotal, (select sum(Sec_Money) from Sec_Info where 1=1
and Sec_Flow_State = #{params.secFlowState}
and Sec_Id in (select Sec_Id from Sec_Project where P_Id=mn.P_Id)) as secMoneyTotal, (select Sec_Create_Uname from Sec_Info where 1=1
and Sec_Flow_State = #{params.secFlowState}
and Sec_Id in (select Sec_Id from Sec_Project where P_Id=mn.P_Id) limit 1) as secCreateUname from Pre_Project mn left join Sec_Project sp on mn.P_Id=sp.P_Id left join Sec_Info sec on sec.Sec_Id=sp.Sec_Id left join Sec_Document sdoc on sec.Sec_Id=sdoc.Sec_Id left join Sys_Department sd on sd.D_Id=mn.P_Competent_Department ${params.authSql} and sdoc.D_Id is not null
and mn.Te_Id = #{params.teId}
and sec.Sec_Flow_State = #{params.secFlowState}
order by mn.P_Create_Time desc

mapper.select:
select sec.Sec_Name as secName, sec.Sec_Money as secMoney, c3.C_Name as dPersonName, c1.C_Name as dManageConsulName, c2.C_Name as dAgentUnitName, c4.C_Name as dEntrustedCpyName, c1.C_Abbreviation as dManageConAbbName, c2.C_Abbreviation as dAgentAbbName, c3.C_Abbreviation as dPersonAbbName, c4.C_Abbreviation as dEntrustedCpyAbbName, c7.C_Name as dCname, dp1.D_Name as dDname, u1.U_Name as dPmName,
sd.*, case when sd.P_Id is null then sp.P_Id else sd.P_Id end as pId from Sec_Document sd left join Sec_Info sec on sec.Sec_Id=sd.Sec_Id left join SYS_Company c3 on c3.C_Id=sd.D_Person left join SYS_Company c1 on c1.C_Id=sd.D_Manage_Consul left join SYS_Company c2 on c2.C_Id=sd.D_Agent_Unit left join SYS_Company c4 on c4.C_Id=sd.D_Entrusted_Cpy left join Sys_Company c7 on c7.C_Id=sd.D_Cid left join Sys_Department dp1 on dp1.D_Id=sd.D_Did left join Sys_User u1 on u1.U_Id=sd.D_Pm_Id left join ( select sp1.Sec_Id, sp1.P_ID, pro1.P_Name, pro1.p_Category, pro1.P_Build_Model, dpre1.D_Name from Sec_Project sp1 inner join pre_project pro1 on pro1.P_Id = sp1.P_Id left join SYS_Department dpre1 on dpre1.D_Id = pro1.p_Competent_Department where not exists ( select 1 from Sec_Project sp2 inner join pre_project pro2 on pro2.P_Id = sp2.P_Id where sp2.Sec_Id = sp1.Sec_Id and pro2.P_Create_Time > pro1.P_Create_Time )) sp on sp.Sec_Id = sd.Sec_Id where 1=1
order by pId asc limit #{params.start},#{params.size}

sql.if:
and (
    (
    CASE WHEN sd.D_New_Bid_Time is not null THEN to_char(sd.D_New_Bid_Time, 'yyyy-MM') ELSE to_char(sd.D_Bid_Time, 'yyyy-MM') END
    ) = #{params.dBidMonYear}
    or (
    select to_char(ssr.Sr_Bid_Time, 'yyyy-MM') from Sec_Selection_Record ssr where  ssr.Sec_Id=sd.Sec_Id and ssr.State!=3 order by ssr.Sr_Bid_Time desc limit 1
    )= #{params.dBidMonYear}
)

and (
(
CASE WHEN sd.D_New_Bid_Time is not null THEN to_char(sd.D_New_Bid_Time, 'yyyy-MM') ELSE to_char(sd.D_Bid_Time, 'yyyy-MM') END
) = #{params.dBidMonYear}
or (
select to_char(ssr.Sr_Bid_Time, 'yyyy-MM') from Sec_Selection_Record ssr where  ssr.Sec_Id=sd.Sec_Id and ssr.State=7 order by ssr.Sr_Bid_Time desc limit 1
)= #{params.dBidMonYear}
)

and (
(
CASE WHEN sd.D_New_Bid_Time is not null THEN date_format(sd.D_New_Bid_Time, '%Y-%m') ELSE date_format(sd.D_Bid_Time, '%Y-%m') END
) = #{params.dBidMonYear}
or (
select date_format(ssr.Sr_Bid_Time, '%Y-%m') from Sec_Selection_Record ssr where  ssr.Sec_Id=sd.Sec_Id and ssr.State=7 order by ssr.Sr_Bid_Time desc limit 1
)= #{params.dBidMonYear}
)
